WITH r AS (SELECT * FROM bestiary_mobs FINAL WHERE zone_id = {zone:Int64} AND mob_name = {name:String} AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')), m AS (SELECT sumMapIfMerge(casts).1 AS spells, sumMapIfMerge(idle_casts).1 AS idle, sumMapIfMerge(results).1 AS taken, sumMapIfMerge(moves).1 AS skills, arrayMap(k -> k.2, sumMapIfMerge(th_items).1) AS items FROM r), rl AS (SELECT DISTINCT release FROM captures WHERE capture_id IN (SELECT capture_id FROM r)) SELECT 'spell' AS kind, id, any(name) AS name FROM spell_names WHERE release IN (SELECT release FROM rl) AND id IN (SELECT arrayJoin(arrayConcat(spells, idle, taken)) FROM m) GROUP BY id UNION ALL SELECT 'skill', id, any(name) FROM mob_skill_names WHERE release IN (SELECT release FROM rl) AND id IN (SELECT arrayJoin(skills) FROM m) GROUP BY id UNION ALL SELECT 'item', id, any(name) FROM item_names WHERE release IN (SELECT release FROM rl) AND id IN (SELECT arrayJoin(items) FROM m) GROUP BY id UNION ALL SELECT 'release', toInt64(0), max(release) FROM rl
